/* Note: Make all modifications to this source file. */

/* 隐藏内置按钮区域 - 插件启用后默认生效, 通过 crb-show-builtin 类来取消隐藏 */
body:not(.is-mobile):not(.crb-show-builtin) .workspace-split.mod-left-split .workspace-sidedock-vault-profile {
  display: none !important;
}

/* 隐藏默认功能区 - 通过 crb-hide-default-actions 类控制 */
body.crb-hide-default-actions .side-dock-actions {
  display: none !important;
}

/* 设置面板样式 - 固定标签页 + 可滚动内容 */

.basic-vault-settings-root {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.basic-vault-settings-tabs {
  display: flex;
  justify-content: flex-start;
  border-bottom: 1px solid var(--background-modifier-border);
  overflow-x: auto;
  padding: 0;
  margin: 0;
  flex-shrink: 0;
}

.basic-vault-settings-tabs::-webkit-scrollbar {
  display: none;
}

.basic-vault-settings-tab {
  padding: 4px 8px;
  margin-bottom: -1px;
  border: 1px solid transparent;
  border-radius: 5px 5px 0 0;
  cursor: pointer;
  font-size: var(--font-ui-medium);
  font-weight: 500;
  color: var(--text-muted);
  border-bottom: 2px solid transparent;
  user-select: none;
}

.basic-vault-settings-tab:hover {
  color: var(--text-normal);
  border-bottom-color: var(--interactive-accent);
}

.basic-vault-settings-tab.is-active {
  color: var(--text-normal);
  font-weight: 600;
  border-bottom-color: var(--interactive-accent);
}

.basic-vault-settings-scroll {
  flex: 1 1 0;
  overflow-y: auto;
  min-height: 0;
}

.basic-vault-settings-content {
  padding-top: 16px;
}

.basic-vault-settings-content .setting-group + .setting-item-heading {
  margin-top: 1.5em;
}

.basic-vault-settings-content .setting-item-control {
  flex-wrap: wrap;
  gap: 8px;
}

.basic-vault-settings-content .setting-item-control > * {
  flex-shrink: 0;
}

/* 按钮设置项 */

.basic-vault-button-setting {
  align-items: center;
}

.basic-vault-button-setting .setting-item-info {
  flex: 1 1 auto;
  min-width: 0;
  padding-right: 12px;
}

.basic-vault-button-setting .setting-item-name,
.basic-vault-button-setting .setting-item-description {
  overflow-wrap: anywhere;
}

.basic-vault-button-setting .setting-item-description {
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}

.basic-vault-button-setting .setting-item-control {
  flex: none;
  margin-left: auto;
}

.basic-vault-button-drag-handle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--input-height);
  height: var(--input-height);
  color: var(--text-muted);
  border-radius: var(--radius-s);
}

.basic-vault-button-drag-handle:hover {
  color: var(--text-normal);
  background-color: var(--background-modifier-hover);
}

.basic-vault-button-name-wrap {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.basic-vault-button-name-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.basic-vault-button-name-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  color: var(--text-muted);
  flex: 0 0 auto;
  pointer-events: none;
}

.basic-vault-button-name-icon-stack {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
}

.basic-vault-button-name-icon-layer {
  position: absolute;
  inset: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
}

.basic-vault-button-name-icon-layer svg {
  width: 16px;
  height: 16px;
}

.basic-vault-confirm-modal {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.basic-vault-confirm-modal > .setting-item-heading {
  padding: 0;
  border: 0;
}

.basic-vault-confirm-modal-message {
  margin: 0;
  color: var(--text-muted);
  line-height: 1.5;
}

.basic-vault-confirm-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.basic-vault-page-header-button {
  order: -1000;
}

@media (max-width: 600px) {
  .basic-vault-button-setting .setting-item-info {
    max-width: 100%;
  }

  .basic-vault-button-setting .setting-item-description {
    overflow-wrap: break-word;
  }

}

/* 按钮相关样式 */

/* 分割线样式 */
.custom-ribbon-divider {
  position: relative;
  margin: 4px 0;
  flex-shrink: 0;
  width: 100%;
  height: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.custom-ribbon-divider::before {
  content: '';
  position: absolute;
  width: 100%;
  height: 1px;
  background-color: var(--divider-color);
  opacity: 0.5;
}

.custom-ribbon-divider:hover::before {
  opacity: 1;
  background-color: var(--divider-color);
}

/* 分割线悬停样式 */
.custom-ribbon-divider:hover {
  background-color: var(--background-modifier-hover);
  border-radius: 2px;
}

/* Pointer Events 排序样式 */

.custom-sort-handle {
  cursor: grab;
}

.custom-sort-container.is-pointer-sorting {
  user-select: none;
}

.custom-sort-item.is-pointer-dragging {
  z-index: 10;
  opacity: 0.55;
}

.custom-sort-container.is-pointer-sorting .custom-sort-item:not(.is-pointer-dragging),
.custom-sort-item.is-pointer-settling {
  transition: translate 160ms cubic-bezier(0.25, 1, 0.5, 1), opacity 120ms ease;
}

.custom-sort-container.is-pointer-sorting
  .custom-sort-item.is-pointer-dragging:not(.is-pointer-settling) {
  transition: opacity 120ms ease;
}

@media (prefers-reduced-motion: reduce) {
  .custom-sort-container.is-pointer-sorting .custom-sort-item:not(.is-pointer-dragging),
  .custom-sort-item.is-pointer-settling {
    transition-duration: 0ms;
  }
}

/* 笔记工具栏和选中文本工具栏 */

.basic-vault-note-toolbar {
  box-sizing: border-box;
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  min-width: 0;
  min-height: 36px;
  padding: 4px var(--size-4-3);
  overflow-x: auto;
  background-color: var(--background-primary);
  border-bottom: 1px solid var(--background-modifier-border);
}

.basic-vault-note-toolbar.is-bottom {
  position: absolute;
  bottom: 4.25em;
  left: max(0%, calc(50% - var(--basic-vault-note-toolbar-width, 0px) / 2));
  z-index: calc(var(--layer-slides) - 1);
  width: max-content;
  max-width: 100%;
  min-height: 0;
  padding: 0 var(--size-4-8);
  overflow: visible;
  background: transparent;
  border-top: 0;
  border-bottom: 0;
  border-radius: 5px;
  visibility: hidden;
}

.basic-vault-note-toolbar.is-bottom.is-aligned {
  visibility: visible;
}

.basic-vault-note-toolbar.is-bottom .basic-vault-content-toolbar-actions {
  padding: 4px;
  background-color: var(--background-primary);
  border: 1px solid var(--background-modifier-border);
  border-radius: 5px;
  box-shadow: var(--shadow-s);
}

.basic-vault-content-toolbar-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  min-width: max-content;
}

.basic-vault-content-toolbar-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 4px;
  color: var(--icon-color);
  border: 0;
  border-radius: var(--clickable-icon-radius);
  background: transparent;
}

.basic-vault-content-toolbar-button:hover {
  color: var(--icon-color-hover);
  background-color: var(--background-modifier-hover);
}

.basic-vault-content-toolbar-button > svg {
  width: var(--icon-size);
  height: var(--icon-size);
}

.basic-vault-content-toolbar-divider {
  flex: 0 0 1px;
  width: 1px;
  height: 18px;
  margin: 0 4px;
  background-color: var(--background-modifier-border);
}

.basic-vault-note-toolbar-divider {
  position: relative;
  flex-basis: 12px;
  width: 12px;
  height: 28px;
  margin: 0;
  background-color: transparent;
}

.basic-vault-note-toolbar-divider::before {
  content: '';
  position: absolute;
  top: 5px;
  bottom: 5px;
  left: 50%;
  width: 1px;
  background-color: var(--background-modifier-border);
  transform: translateX(-50%);
  pointer-events: none;
}

.basic-vault-note-toolbar-divider:hover,
.basic-vault-note-toolbar-divider.is-pointer-dragging {
  background-color: var(--background-modifier-hover);
  border-radius: var(--clickable-icon-radius);
}

.basic-vault-note-toolbar-divider:hover::before,
.basic-vault-note-toolbar-divider.is-pointer-dragging::before {
  background-color: var(--icon-color-hover);
}

.basic-vault-selection-toolbar {
  box-sizing: border-box;
  position: fixed;
  top: var(--basic-vault-selection-toolbar-top, 0);
  left: var(--basic-vault-selection-toolbar-left, 0);
  z-index: var(--layer-popover, 1000);
  display: flex;
  max-width: calc(100vw - 16px);
  padding: 4px;
  overflow-x: auto;
  visibility: hidden;
  pointer-events: none;
  opacity: 0;
  transform: translateY(2px);
  background-color: var(--background-primary-alt);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
  box-shadow: var(--shadow-s);
  transition: opacity 100ms ease, transform 100ms ease;
}

.basic-vault-selection-toolbar.is-visible {
  visibility: visible;
  pointer-events: auto;
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  .basic-vault-selection-toolbar {
    transition-duration: 0ms;
  }
}

/* 按钮组菜单 */

.basic-vault-has-button-group {
  position: relative;
}

.basic-vault-has-button-group::after {
  content: '';
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 0;
  height: 0;
  border-top: 3px solid currentColor;
  border-right: 3px solid transparent;
  border-left: 3px solid transparent;
  opacity: 0.65;
  pointer-events: none;
}

.menu-item[data-section^='basic-vault-button-group-'] {
  min-height: 30px;
}

.menu-item[data-section='basic-vault-button-group-ribbon'],
.menu-item[data-section='basic-vault-button-group-note'],
.menu-item[data-section='basic-vault-button-group-selection'] {
  min-height: 28px;
  padding-top: 3px;
  padding-bottom: 3px;
  font-size: var(--font-ui-small);
}

.menu-item[data-section='basic-vault-button-group-selection'] {
  min-height: 26px;
  font-size: var(--font-ui-smaller);
}

.menu-item[data-section^='basic-vault-button-group-'] .menu-item-icon {
  --icon-size: var(--icon-s);
}

.basic-vault-button-studio-modal-shell {
  width: min(660px, calc(100vw - 24px));
  max-width: min(660px, calc(100vw - 24px));
}

.basic-vault-button-studio {
  display: flex;
  flex-direction: column;
  padding: 2px;
  box-sizing: border-box;
}

.basic-vault-button-studio > .setting-item {
  min-height: 48px;
  padding: 8px 0;
}

.basic-vault-button-studio > .setting-item > .setting-item-info {
  flex: 0 0 190px;
  min-width: 0;
}

.basic-vault-button-studio > .setting-item > .setting-item-control {
  flex: 1 1 auto;
  min-width: 0;
}

.basic-vault-button-studio > .setting-item > .setting-item-control input[type='text'] {
  width: 100%;
  min-width: 0;
}

.basic-vault-button-studio-icon-picker.clickable-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 4px;
}

.basic-vault-button-studio-icon-preview {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
}

.basic-vault-button-studio-icon-preview svg {
  width: 16px;
  height: 16px;
}

.basic-vault-button-group-form {
  display: flex;
  flex-direction: column;
  width: 100%;
}

.basic-vault-button-group-form-row {
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
  align-items: center;
  gap: 16px;
  min-height: 48px;
  padding: 8px 0;
  border-top: 1px solid var(--background-modifier-border);
}

.basic-vault-button-group-form-row:first-child {
  border-top: 0;
}

.basic-vault-button-group-form-row.is-list {
  align-items: start;
}

.basic-vault-button-group-form-info,
.basic-vault-button-group-form-control {
  min-width: 0;
}

.basic-vault-button-group-form-name,
.basic-vault-button-group-item-name {
  color: var(--text-normal);
  font-size: var(--font-ui-small);
  line-height: 1.4;
}

.basic-vault-button-group-form-description,
.basic-vault-button-group-item-description,
.basic-vault-button-group-empty {
  margin-top: 2px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
  line-height: var(--line-height-tight);
  overflow-wrap: anywhere;
}

.basic-vault-button-group-form-control {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: 100%;
}

.basic-vault-button-group-form-control > input[type='text'] {
  width: 100%;
  min-width: 0;
}

.basic-vault-button-group-list,
.basic-vault-button-group-items {
  width: 100%;
  min-width: 0;
}

.basic-vault-button-group-item {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) max-content;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 48px;
  padding: 8px 0;
  border-bottom: 1px solid var(--background-modifier-border);
}

.basic-vault-button-group-item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
}

.basic-vault-button-group-item-icon svg {
  width: 16px;
  height: 16px;
}

.basic-vault-button-group-item-info {
  min-width: 0;
}

.basic-vault-button-group-item-actions {
  display: flex;
  align-items: center;
  gap: 1px;
}

.basic-vault-button-group-drag-handle {
  touch-action: none;
}

.basic-vault-button-group-empty {
  padding: 10px 0;
}

.basic-vault-button-group-add.clickable-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 100%;
  height: 30px;
  padding: 4px 8px;
  border: 0;
  background-color: transparent;
  box-shadow: none;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.basic-vault-button-group-add.clickable-icon:hover {
  background-color: var(--background-modifier-hover);
  color: var(--text-normal);
  cursor: pointer;
}

@media (max-width: 600px) {
  .basic-vault-button-studio > .setting-item {
    align-items: initial;
    flex-direction: column;
    gap: 6px;
  }

  .basic-vault-button-studio > .setting-item > .setting-item-info {
    flex-basis: auto;
  }

  .basic-vault-button-studio > .setting-item > .setting-item-control {
    width: 100%;
  }

  .basic-vault-button-group-form-row {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .basic-vault-button-group-form-control {
    justify-content: flex-start;
  }
}


#better-export-pdf {
  display: flex;
  flex-direction: row;
  height: 100%;
  width: 100%;
  min-width: 0;
  min-height: 0;

  .print-preview {
    flex: 1;
    min-width: 0;
    overflow-x: hidden;
    overflow-y: scroll;
    position: relative;
    display: flex;
    flex-direction: column;
    align-content: flex-start;
  }

  .setting-wrapper {
    width: 320px;
    flex: 0 0 320px;
    margin-left: 16px;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
  }

  .setting-scroll {
    flex: 1;
    overflow-y: auto;
    scrollbar-gutter: stable;
    padding: 20px;
  }

  .setting-scroll::-webkit-scrollbar {
    width: 8px;
  }

  .setting-scroll::-webkit-scrollbar-track {
    background: transparent;
  }

  .setting-scroll::-webkit-scrollbar-thumb {
    background: var(--background-modifier-border);
    border-radius: 4px;
  }

  .setting-scroll::-webkit-scrollbar-thumb:hover {
    background: var(--background-modifier-border-hover);
  }

  .setting-actions {
    flex-shrink: 0;
    padding: 16px 20px;
    border-top: 1px solid var(--background-modifier-border);
    background: var(--background-primary);
  }

  .setting-actions .setting-item {
    border-top: none;
    padding: 0;
  }

  .albus-export-pdf-full-width-button {
    margin: 0 auto;
    width: -webkit-fill-available;
  }

  .albus-export-pdf-number-input {
    width: 100px;
  }

  .setting-wrapper .setting-item[hidden] {
    display: none;
  }

  .preview-wrapper {
    position: relative;
    width: 100%;
    min-height: 100%;
    box-sizing: border-box;
  }

  .pdf-preview-pages {
    display: flex;
    flex-direction: column;
    gap: var(--size-4-4);
    width: 100%;
  }

  .pdf-canvas-page {
    width: 100%;
    height: auto;
    flex: none;
    border: 1px solid var(--background-modifier-border);
    background: white;
    box-sizing: border-box;
  }

  .pdf-canvas-page canvas {
    width: 100% !important;
    height: auto !important;
    display: block;
  }

  .icon svg {
    width: var(--icon-xs) !important;
    height: var(--icon-xs) !important;
  }
}

.albus-export-pdf-modal .modal {
  width: var(--modal-width);
  height: var(--modal-height);
  max-width: var(--modal-max-width);
  max-height: var(--modal-max-height);
}

.albus-export-pdf-modal .modal-content {
  flex: 1;
  width: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

/* 必须有此样式, 否则大纲锚点失效 */
@media print {
  .print .markdown-preview-view {
    height: auto !important;
  }
  .md-print-anchor,
  .blockid {
    white-space: pre !important;
    border-left: none !important;
    border-right: none !important;
    border-top: none !important;
    border-bottom: none !important;
    display: inline-block !important;
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    right: 0 !important;
    outline: 0 !important;
    background: 0 0 !important;
    text-decoration: initial !important;
    text-shadow: initial !important;
  }
}

