	background: color-mix(in srgb, var(--interactive-accent) 12%, var(--background-secondary));
}

.mbv-frontmatter-preview-summary-label,
.mbv-frontmatter-preview-summary-value {
	display: block;
	overflow: hidden;
	text-overflow: ellipsis;
}

.mbv-frontmatter-preview-summary-label {
	color: var(--text-muted);
	font-size: var(--font-ui-smaller);
}

.mbv-frontmatter-preview-summary-value {
	margin-top: var(--size-2-2);
	font-size: var(--font-ui-medium);
	font-weight: var(--font-semibold);
}

.mbv-frontmatter-preview-list {
	max-height: min(420px, 50vh);
	overflow: auto;
	border-block: var(--border-width) solid var(--background-modifier-border);
}

.mbv-frontmatter-preview-row {
	display: grid;
	grid-template-columns: auto minmax(0, 1fr) auto;
	align-items: center;
	gap: var(--size-4-2);
	min-height: var(--bases-table-row-height);
	padding: var(--size-2-2) var(--size-4-1);
	border-bottom: var(--border-width) solid var(--background-modifier-border);
	font-size: var(--font-ui-small);
}

.mbv-frontmatter-preview-icon {
	display: flex;
	color: var(--icon-color);
	--icon-size: var(--icon-xs);
}

.mbv-frontmatter-preview-row.is-conflict .mbv-frontmatter-preview-icon {
	color: var(--text-error);
}

.mbv-frontmatter-preview-row.is-blocking {
	background: color-mix(in srgb, var(--background-modifier-error) 42%, transparent);
}

.mbv-frontmatter-preview-path {
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.mbv-frontmatter-preview-description,
.mbv-frontmatter-preview-more {
	color: var(--text-muted);
}

.mbv-frontmatter-preview-more {
	padding: var(--size-4-2);
	font-size: var(--font-ui-smaller);
	text-align: center;
}

.mbv-frontmatter-preview-actions.setting-item {
