	font-size: var(--font-ui-medium);
}

.mbv-html-export-progress-bar {
	width: 100%;
}

.mbv-html-export-progress-actions {
	display: flex;
	justify-content: flex-end;
	margin-top: 14px;
}

.mbv-bases-view-tab-list {
	display: flex;
	min-width: 0;
	align-items: center;
	gap: var(--size-2-1);
	overflow-x: auto;
	overflow-y: hidden;
	scrollbar-width: none;
}

.mbv-bases-view-tab-list::-webkit-scrollbar {
	display: none;
}

.mbv-bases-view-tab.clickable-icon {
	position: relative;
	min-width: 0;
	width: auto;
	height: var(--input-height);
	min-height: var(--input-height);
	justify-content: flex-start;
	gap: var(--size-4-1);
	padding: 0 var(--size-2-3);
	font-family: var(--font-interface);
	font-size: var(--font-ui-small);
	font-weight: var(--font-medium);
	white-space: nowrap;
	user-select: none;
	transition: background-color 120ms ease, color 120ms ease, opacity 120ms ease;
}

.mbv-bases-view-tab.clickable-icon.is-dragging {
	z-index: 2;
	opacity: 0.5;
}

.mbv-bases-view-tab-list.is-sorting .mbv-bases-view-tab.clickable-icon:not(.is-dragging),
.mbv-bases-view-tab.clickable-icon.is-settling {
	transition: background-color 120ms ease, color 120ms ease, opacity 120ms ease,
		translate 160ms cubic-bezier(0.25, 1, 0.5, 1);
}

.mbv-bases-view-tab-list.is-sorting .mbv-bases-view-tab.clickable-icon.is-dragging:not(.is-settling) {
	transition: background-color 120ms ease, color 120ms ease, opacity 120ms ease;
}

.mbv-bases-view-tab.clickable-icon.is-active {
	background: var(--background-modifier-hover);
	color: var(--text-normal);
}

.mbv-bases-view-tab-icon {
	display: inline-flex;
	flex: 0 0 auto;
	align-items: center;
}

.mbv-bases-view-tab-icon svg {
	width: var(--icon-s);
	height: var(--icon-s);
	stroke-width: var(--icon-s-stroke-width);
}

.mbv-bases-view-tab-name {
	overflow: hidden;
	text-overflow: ellipsis;
}

.mbv-bases-view-add.clickable-icon {
	flex: 0 0 auto;
	height: var(--input-height);
	min-height: var(--input-height);
}

.bases-header.mbv-bases-tabs-enabled .bases-toolbar-result-count {
