@container bases-header (width < 540px) {
	.mbv-bases-view-tabs {
		max-width: 62%;
	}
}

.mbv-book-view {
	display: flex;
	width: 100%;
	min-height: 100%;
	box-sizing: border-box;
	flex-direction: column;
	gap: 12px;
	padding: 20px;
	color: var(--text-normal);
}

.mbv-book-grid {
	display: grid;
	width: 100%;
	grid-template-columns: repeat(var(--mbv-viewport-grid-columns, 1), minmax(0, 1fr));
	align-items: start;
	gap: 32px 24px;
}

.mbv-book-card {
	display: flex;
	min-width: 0;
	flex-direction: column;
	cursor: pointer;
}

.mbv-book-slot {
	min-width: 0;
}

.mbv-book-shell {
	position: relative;
	width: 100%;
	border-radius: 2px 6px 6px 2px;
	perspective: 1200px;
}

.mbv-book-shell::before {
	display: block;
	padding-top: calc(3 / 2 * 100%);
	content: '';
}

.mbv-book-shadow {
	position: absolute;
	bottom: -6px;
	left: 5%;
	width: 90%;
	height: 12px;
	border-radius: 50%;
	background: rgb(0 0 0 / 35%);
	filter: blur(6px);
	opacity: 0.5;
	transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1),
		opacity 0.5s ease;
}

.mbv-book-card:hover .mbv-book-shadow,
.mbv-book-card:focus-within .mbv-book-shadow {
	transform: translateX(8px) scale(0.95);
	opacity: 0.8;
}

.mbv-book-box {
	position: absolute;
	inset: 0;
	z-index: 2;
	transform: rotateX(0deg) rotateY(0deg) scale(1);
	transform-style: preserve-3d;
	transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mbv-book-card:hover .mbv-book-box,
.mbv-book-card:focus-within .mbv-book-box {
	transform: rotateX(4deg) rotateY(24deg) scale(1.02);
}

.mbv-book-front {
	position: absolute;
	inset: 0;
	overflow: hidden;
	border-radius: 2px 6px 6px 2px;
	background: var(--background-primary);
	box-shadow: inset 1px 1px 0 1px rgb(255 255 255 / 20%),
		inset 0 0 0 1px rgb(0 0 0 / 10%),
		-4px 2px 6px 0 rgb(0 0 0 / 25%),
		-8px 8px 24px 0 rgb(0 0 0 / 25%);
	transform: translateZ(10px);
	transition: box-shadow 0.5s ease;
}

.mbv-book-card:hover .mbv-book-front,
.mbv-book-card:focus-within .mbv-book-front {
	box-shadow: inset 1px 1px 0 1px rgb(255 255 255 / 20%),
		inset 0 0 0 1px rgb(0 0 0 / 10%),
		-6px 4px 12px 0 rgb(0 0 0 / 30%),
		-12px 12px 32px 0 rgb(0 0 0 / 40%);
}

.mbv-book-front::after {
	position: absolute;
	inset: 0;
	z-index: 5;
	pointer-events: none;
	content: '';
	background-image: linear-gradient(
		to right,
		rgb(0 0 0 / 30%) 0%,
		rgb(255 255 255 / 25%) 2%,
		transparent 5%,
		rgb(0 0 0 / 15%) 6%,
		rgb(255 255 255 / 15%) 8%,
		transparent 15%
	);
}

.mbv-book-cover-link,
.mbv-book-cover,
.mbv-book-cover-native-value,
.mbv-book-cover-native-value > a {
	display: block;
	width: 100%;
	height: 100%;
}

.mbv-book-cover-link {
	position: absolute;
	inset: 0;
	color: inherit;
	text-decoration: none;
}

.mbv-book-cover {
	position: relative;
	overflow: hidden;
}

.mbv-book-cover::after {
	position: absolute;
	inset: 0;
	z-index: 4;
	pointer-events: none;
	background: linear-gradient(
		115deg,
		rgb(255 255 255 / 10%) 0%,
		transparent 24%,
		transparent 72%,
		rgb(0 0 0 / 5%) 100%
	);
	content: '';
}

.mbv-book-cover-placeholder {
	position: absolute;
	inset: 0;
	background: var(--background-primary-alt);
	border-radius: 2px 6px 6px 2px;
}

.mbv-book-cover.has-cover .mbv-book-cover-placeholder {
	display: none;
}

.mbv-book-cover-image,
.mbv-book-cover-native-value img {
	display: block;
	width: 100%;
	height: 100%;
	object-fit: cover;
	border-radius: 2px 6px 6px 2px;
	opacity: 1;
	transition: opacity 0.35s ease;
}

.mbv-book-cover-image.is-loading {
	opacity: 0;
}

.mbv-book-spine {
	position: absolute;
	top: 0;
	left: 0;
	display: flex;
	width: 20px;
	height: 100%;
	align-items: center;
	justify-content: center;
	overflow: hidden;
	border-radius: 4px 0 0 4px;
	background: var(--background-secondary);
	box-shadow: inset 1px 0 0 rgb(255 255 255 / 15%);
	transform: translateZ(10px) rotateY(-90deg) translateX(-20px);
	transform-origin: left center;
}

.mbv-book-spine-image {
	position: absolute;
	top: 50%;
	left: 0;
	z-index: 0;
	width: 25%;
	height: 100%;
	object-fit: cover;
	object-position: left center;
	filter: brightness(0.82) saturate(0.96);
	transform: translateY(-50%) translateZ(0) scaleX(4);
	transform-origin: left center;
}

.mbv-book-spine-image.is-hidden {
	display: none;
}

.mbv-book-spine-overlay {
	position: absolute;
	inset: 0;
	z-index: 1;
	background: linear-gradient(
		to right,
		rgb(255 255 255 / 18%) 0%,
		transparent 22%,
		rgb(0 0 0 / 18%) 100%
	);
}

.mbv-book-spine-title {
	position: relative;
	z-index: 2;
	overflow: hidden;
	max-height: 90%;
	color: rgb(255 255 255 / 95%);
	font-size: 11px;
	font-weight: 700;
	letter-spacing: 2px;
	text-align: center;
	text-overflow: ellipsis;
	text-orientation: mixed;
	text-shadow: 0 1px 4px rgb(0 0 0 / 80%);
	white-space: nowrap;
	writing-mode: vertical-rl;
}

.mbv-book-action {
	position: absolute;
	z-index: 20;
	box-sizing: border-box;
	border: 0;
	border-radius: var(--radius-s);
	background: var(--background-primary);
	box-shadow: 0 1px 3px rgb(0 0 0 / 20%);
	color: var(--icon-color);
	line-height: 0;
	opacity: 0;
	transition: background-color 0.15s ease, opacity 0.15s ease;
}

.mbv-book-card:hover .mbv-book-action,
.mbv-book-card:focus-within .mbv-book-action {
	opacity: 1;
}

.mbv-book-action:hover {
	background: var(--background-modifier-hover);
	color: var(--text-normal);
}

.mbv-book-action.is-hidden {
	display: none;
}

.mbv-book-open-action {
	top: 8px;
	left: 8px;
	width: auto;
	height: auto;
	min-width: 0;
	min-height: 0;
	padding: 3px 5px;
	appearance: none;
	cursor: pointer;
	font: inherit;
}

.mbv-book-open-action svg {
	width: 16px;
	height: 16px;
}

.mbv-book-status-action {
	top: 8px;
	right: 8px;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: 3px 5px;
}

.mbv-book-status-action input[type='checkbox'] {
	width: 16px;
	height: 16px;
	margin: 0 !important;
	padding: 0 !important;
	cursor: pointer;
	display: block;
	flex-shrink: 0;
}

.mbv-visually-hidden {
	position: absolute !important;
	width: 1px !important;
	height: 1px !important;
	padding: 0 !important;
	margin: -1px !important;
	overflow: hidden !important;
	clip: rect(0, 0, 0, 0) !important;
	white-space: nowrap !important;
	border: 0 !important;
}

.mbv-book-card-body {
	padding: 12px 4px 0;
}

@media (hover: none) {
	.mbv-book-action {
		opacity: 1;
	}
}

.mbv-paper-view {
	display: flex;
	width: 100%;
	min-height: 100%;
	box-sizing: border-box;
	flex-direction: column;
	gap: 12px;
	padding: 20px;
	color: var(--text-normal);
}

.mbv-paper-grid {
	display: grid;
	width: 100%;
	grid-template-columns: repeat(var(--mbv-viewport-grid-columns, 1), minmax(0, 1fr));
	align-items: start;
	gap: 20px 24px;
}

.mbv-paper-slot {
	min-width: 0;
}

.mbv-paper-card {
	position: relative;
	display: flex;
	min-width: 0;
	flex-direction: column;
	overflow: visible;
	box-shadow: none;
}

.mbv-paper-cover-shell {
	position: relative;
	display: block;
	width: 100%;
	overflow: visible;
	border-radius: 4px;
	color: inherit;
	cursor: pointer;
	text-decoration: none;
}

.mbv-paper-cover-shell::before {
	display: block;
	padding-top: 141.4%;
	content: '';
}

.mbv-paper-cover {
	position: absolute;
	inset: 0;
	display: flex;
	flex-direction: column;
	overflow: hidden;
	border: 1px solid var(--background-modifier-border);
	border-top: 4px solid var(--text-normal);
	border-radius: 3px;
	background: var(--background-primary);
	box-shadow: 0 1px 3px rgb(0 0 0 / 4%), 0 3px 8px rgb(0 0 0 / 4%);
	transition: overflow 0s 0.25s, transform 0.2s ease-out,
		box-shadow 0.2s ease-out;
}

.mbv-paper-card:hover .mbv-paper-cover,
.mbv-paper-card:focus-within .mbv-paper-cover {
	overflow: visible;
	box-shadow: 0 4px 10px rgb(0 0 0 / 6%), 0 12px 24px rgb(0 0 0 / 8%);
	transform: translateY(-4px);
	transition: overflow 0s, transform 0.2s ease-out, box-shadow 0.2s ease-out;
}

.mbv-paper-cover::after {
	position: absolute;
	top: 42%;
	right: 14%;
	bottom: 12%;
	left: 14%;
	pointer-events: none;
	background-image: linear-gradient(
			to bottom,
			var(--text-normal) 2px,
			transparent 2px
		),
		linear-gradient(
			to bottom,
			var(--text-normal) 2px,
			transparent 2px
		);
	background-position: left top, right top;
	background-repeat: repeat-y;
	background-size: 46% 8px, 46% 8px;
	content: '';
	opacity: 0.06;
}

.mbv-paper-cover-content {
	position: relative;
	z-index: 1;
	display: flex;
