.mbv-game-view {
	display: flex;
	flex-direction: column;
	width: 100%;
	box-sizing: border-box;
	padding: 30px 20px 40px;
}

.mbv-game-grid {
	display: grid;
	grid-template-columns: repeat(var(--mbv-viewport-grid-columns, 1), minmax(0, 1fr));
	gap: 40px 24px;
	align-items: start;
}

.mbv-game-slot {
	position: relative;
	min-width: 0;
	overflow: visible;
}

.mbv-game-slot:hover,
.mbv-game-slot:focus-within {
	z-index: 50;
}

.mbv-game-card {
	position: relative;
	display: flex;
	flex-direction: column;
	min-width: 0;
	z-index: 1;
}

.mbv-game-shell {
	position: relative;
	display: block;
	width: 100%;
	aspect-ratio: 3 / 4;
	border-radius: 8px;
	color: inherit;
	text-decoration: none;
	outline: none;
}

.mbv-game-shell:hover,
.mbv-game-shell:focus-within {
	color: inherit;
	text-decoration: none;
}

.mbv-game-shell:focus-visible .mbv-game-case {
	outline: 2px solid var(--interactive-accent);
	outline-offset: 2px;
}

.mbv-game-disc {
	position: absolute;
	top: 5%;
	left: 10%;
	width: 80%;
	aspect-ratio: 1;
	opacity: 0;
	transform: translateY(20%) scale(0.6);
	transition: transform 600ms cubic-bezier(0.34, 1.56, 0.64, 1), opacity 400ms ease;
	z-index: 1;
}

.mbv-game-card:hover .mbv-game-disc,
.mbv-game-card:focus-within .mbv-game-disc {
	opacity: 1;
	transform: translateY(-40%) scale(0.95);
}

.mbv-game-disc-spinner {
	position: relative;
	width: 100%;
	height: 100%;
	overflow: hidden;
	border-radius: 50%;
	background: #111;
	box-shadow: 0 4px 24px rgb(0 0 0 / 70%), 0 0 0 1px rgb(255 255 255 / 8%);
	mask-image: radial-gradient(circle at center, transparent 10%, #000 11.5%);
	animation: mbv-game-disc-spin 6s linear infinite paused;
}

.mbv-game-card:hover .mbv-game-disc-spinner,
.mbv-game-card:focus-within .mbv-game-disc-spinner {
	animation-play-state: running;
