}

.mbv-game-disc-image,
.mbv-game-case-image {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	object-fit: cover;
}

.mbv-game-disc-overlay {
	position: absolute;
	inset: 0;
	background: conic-gradient(
		rgb(255 255 255 / 10%) 0deg,
		transparent 45deg,
		rgb(255 255 255 / 20%) 90deg,
		transparent 135deg,
		rgb(255 255 255 / 10%) 180deg,
		transparent 225deg,
		rgb(255 255 255 / 20%) 270deg,
		transparent 315deg,
		rgb(255 255 255 / 10%) 360deg
	);
	mix-blend-mode: screen;
	pointer-events: none;
}

.mbv-game-disc-hole {
	position: absolute;
	top: 50%;
	left: 50%;
	width: 21%;
	aspect-ratio: 1;
	border: 2px solid rgb(255 255 255 / 25%);
	border-radius: 50%;
	box-shadow: inset 0 0 8px rgb(0 0 0 / 90%), 0 0 4px rgb(0 0 0 / 50%);
	transform: translate(-50%, -50%);
	pointer-events: none;
