@container mbv-index (max-width: 1100px) {
	.mbv-index-body {
		grid-template-columns: 240px minmax(260px, 1fr);
	}
}

@container mbv-index (max-width: 720px) {
	.mbv-index-toolbar {
		padding-right: 8px;
		padding-left: 8px;
	}

	.mbv-index-body {
		display: flex;
		flex-direction: column;
