	.mbv-index-nav {
		display: flex;
		min-height: 46px;
		max-height: 46px;
		padding: 5px 7px;
		border-right: 0;
		border-bottom: 1px solid var(--background-modifier-border);
		align-items: center;
		overflow-x: auto;
		overflow-y: hidden;
		gap: 3px;
	}

	.mbv-index-nav-item {
		width: auto;
		min-width: max-content;
		padding: 0 9px;
