/* 干员视图 */
.mbv-operator-view {
	position: relative;
	display: flex;
	width: 100%;
	min-height: 100%;
	box-sizing: border-box;
	padding: 10px 24px 52px;
	flex-direction: column;
	color: var(--text-normal);
}

.mbv-operator-grid {
	display: grid;
	width: 100%;
	grid-template-columns: repeat(var(--mbv-viewport-grid-columns, 1), minmax(0, 1fr));
	align-items: start;
	gap: 64px 32px;
}

.mbv-operator-slot {
	position: relative;
	min-width: 0;
	overflow: visible;
	background: transparent;
}

.mbv-operator-slot:hover,
.mbv-operator-slot:focus-within {
	z-index: 80;
}

.mbv-operator-card {
	position: relative;
	--mbv-operator-control-tilt-x: 0deg;
	--mbv-operator-control-tilt-y: 0deg;
	--mbv-operator-control-lift: 0px;
	display: flex;
	min-width: 0;
	background: transparent;
	container-type: inline-size;
	flex-direction: column;
}

.mbv-operator-shell {
	position: relative;
	display: block;
	width: 100%;
	background: transparent;
	color: inherit;
	text-decoration: none;
	outline: none;
	transform: none;
	transform-origin: 50% 48%;
	transition: transform 280ms cubic-bezier(0.2, 0.8, 0.2, 1);
	z-index: 1;
}

.mbv-operator-card:hover,
.mbv-operator-card:focus-within {
	--mbv-operator-control-lift: -2px;
}

.mbv-operator-card:hover .mbv-operator-shell,
.mbv-operator-card:focus-within .mbv-operator-shell {
	color: inherit;
	text-decoration: none;
	transform: translateY(-2px);
	z-index: 3;
}

.mbv-operator-frame {
	--mbv-operator-tilt-x: 0deg;
	--mbv-operator-tilt-y: 0deg;
	--mbv-operator-brightness: 1;
	--mbv-operator-shadow-x: 0px;
	--mbv-operator-shadow-y: 0px;
	--mbv-operator-art-x: 0px;
	--mbv-operator-art-y: 0px;
	--mbv-operator-logo-x: 0px;
	--mbv-operator-logo-y: 0px;
	--mbv-operator-logo-shadow-x: 0px;
	--mbv-operator-logo-shadow-y: 0px;
	--mbv-operator-artwork-size: 148%;
	--mbv-operator-artwork-left: -24%;
	--mbv-operator-artwork-top: 0%;
	--mbv-operator-artwork-focus-x: 0%;
	--mbv-operator-artwork-focus-y: 0%;
	--mbv-operator-artwork-base-y: 3cqw;
	--mbv-operator-profession-glow: #b9c2cf;
	--mbv-operator-faction-glow: #c4ccd6;
	--mbv-operator-rarity-glow: #a8b0ba;
	position: relative;
	width: 100%;
	aspect-ratio: 120 / 250;
	background: transparent;
	box-shadow: none;
	transform:
		perspective(1000px)
		rotateY(var(--mbv-operator-tilt-y))
		rotateX(var(--mbv-operator-tilt-x));
	transform-style: preserve-3d;
	transition: transform 200ms ease, box-shadow 100ms ease;
	container-type: inline-size;
}


.mbv-operator-shell:hover .mbv-operator-frame,
.mbv-operator-shell:focus-visible .mbv-operator-frame {
	box-shadow: none;
}

.mbv-operator-shell:focus-visible .mbv-operator-clip {
	outline: 2px solid var(--interactive-accent);
	outline-offset: 3px;
}

.mbv-operator-clip {
	position: absolute;
	inset: 0;
	overflow: hidden;
	background: transparent;
	isolation: isolate;
}

.mbv-operator-rarity-header,
.mbv-operator-profession-shadow,
.mbv-operator-rarity-banner,
.mbv-operator-rarity-glow,
.mbv-operator-rarity-background,
.mbv-operator-artwork,
.mbv-operator-patch,
.mbv-operator-footer {
	position: absolute;
	pointer-events: none;
}

.mbv-operator-rarity-header,
.mbv-operator-profession-shadow {
	top: 0;
	left: 0;
	display: block;
	width: 58.3333%;
	height: auto;
	object-fit: contain;
	object-position: 0 0;
	z-index: 3;
}

.mbv-operator-profession-shadow {
	z-index: 4;
}

.mbv-operator-rarity {
	position: absolute;
	top: 0;
	left: 25%;
	display: block;
	width: 75%;
	height: 7.2%;
	pointer-events: none;
	transform: translate3d(0, 0, 28px) scale(1);
	transform-style: preserve-3d;
	transition: transform 400ms ease, filter 100ms ease-out;
	z-index: 9;
}

.mbv-operator-rarity-track {
	position: absolute;
	inset: 0;
	display: flex;
	align-items: flex-start;
	transform: translate3d(var(--mbv-operator-logo-x), var(--mbv-operator-logo-y), 0);
	transition: transform 100ms ease-out;
}

.mbv-operator-stars {
	display: block;
	width: auto;
	max-width: none;
	height: 100%;
	object-fit: contain;
	object-position: 0 0;
	filter: drop-shadow(0 1px 1px rgb(0 0 0 / 65%));
	backface-visibility: hidden;
}

.mbv-operator-rarity-background {
	bottom: 2.8%;
	left: 2.5%;
	display: block;
	width: 91.6667%;
	height: auto;
	object-fit: contain;
	object-position: 0 100%;
	z-index: 0;
}

.mbv-operator-artwork {
	top: 1.2%;
	right: 5.8333%;
	bottom: 11.6%;
	left: 2.5%;
	overflow: hidden;
	contain: paint;
	background: transparent;
	z-index: 0;
}

.mbv-operator-artwork-motion {
	position: absolute;
	inset: 0;
	display: flex;
	align-items: flex-end;
	justify-content: flex-end;
	filter:
		brightness(var(--mbv-operator-brightness))
		drop-shadow(
			calc(var(--mbv-operator-shadow-x) / 2)
			calc(var(--mbv-operator-shadow-y) / 2)
			5px
			rgb(0 0 20 / 20%)
		);
	transform:
		translate3d(
			calc(
				var(--mbv-operator-artwork-focus-x) +
				var(--mbv-operator-art-x)
			),
			calc(
				var(--mbv-operator-artwork-base-y) +
				var(--mbv-operator-artwork-focus-y) +
				var(--mbv-operator-art-y)
			),
			16px
		);
	transform-style: preserve-3d;
	transition: transform 100ms ease-out, filter 100ms ease-out;
}

.mbv-operator-artwork-layout {
	position: absolute;
	top: var(--mbv-operator-artwork-top);
	left: var(--mbv-operator-artwork-left);
	z-index: 1;
	width: var(--mbv-operator-artwork-size);
	height: var(--mbv-operator-artwork-size);
	opacity: 1;
	visibility: visible;
	transition:
		opacity 320ms cubic-bezier(0.22, 0.61, 0.36, 1),
		visibility 0s linear 0s;
}

.mbv-operator-artwork-layout.is-active {
	z-index: 2;
}

.mbv-operator-artwork-layout.is-hidden {
	opacity: 0;
	visibility: hidden;
	transition:
		opacity 320ms cubic-bezier(0.22, 0.61, 0.36, 1),
		visibility 0s linear 320ms;
}

.mbv-operator-artwork-image {
	display: block;
	width: 100%;
	height: 100%;
	max-width: none;
	max-height: none;
	object-fit: contain;
	object-position: 50% 0;
}

.mbv-operator-artwork-image.is-hidden {
	visibility: hidden;
}


.mbv-operator-rarity-glow {
	bottom: 10%;
	left: 2.5%;
	display: block;
	width: 91.6667%;
	height: auto;
	object-fit: contain;
	object-position: 0 100%;
	z-index: 1;
}

.mbv-operator-patch {
	bottom: 2.8%;
	left: 2.5%;
	width: 66.6667%;
	height: 12%;
	background: #2c2c2c;
	z-index: 1;
}

.mbv-operator-rarity-banner {
	bottom: 0;
	left: 0;
	display: block;
	width: 100%;
	height: auto;
	object-fit: contain;
	object-position: 0 100%;
	z-index: 2;
}

.mbv-operator-footer {
	inset: 0;
	z-index: 3;
}

.mbv-operator-identity {
	position: absolute;
	inset: 0;
	color: #fff;
}

.mbv-operator-code,
.mbv-operator-name {
	position: absolute;
	overflow: hidden;
	color: #fff;
	font-weight: 500;
	line-height: 1;
	text-align: center;
