}

.mbv-operator-profession,
.mbv-operator-faction,
.mbv-operator-rarity {
	position: absolute;
	display: block;
	pointer-events: none;
	transform-style: preserve-3d;
	transition: transform 400ms ease, filter 100ms ease-out;
	z-index: 8;
}

.mbv-operator-rarity {
	z-index: 9;
}

.mbv-operator-profession {
	top: 2%;
	left: 2.5%;
