	inset: 0;
	transition: transform 100ms ease-out;
}

.mbv-operator-profession-track,
.mbv-operator-faction-track,
.mbv-operator-rarity-track {
	transform:
		translate3d(
			var(--mbv-operator-logo-x),
			var(--mbv-operator-logo-y),
			0
		);
