.mbv-operator-card:hover .mbv-operator-potential-toggle.clickable-icon,
.mbv-operator-card:focus-within .mbv-operator-potential-toggle.clickable-icon,
.mbv-operator-potential-toggle.clickable-icon:hover,
.mbv-operator-potential-toggle.clickable-icon:focus-visible {
	background: transparent;
	box-shadow: none;
	filter: drop-shadow(0 0 3px rgb(35 145 205 / 48%));
	opacity: 1;
}

.mbv-operator-potential-image {
	position: absolute;
	inset: 0;
	display: block;
	width: 100%;
	height: 100%;
	object-fit: contain;
	pointer-events: none;
	filter: drop-shadow(0 1px 2px rgb(0 0 0 / 62%));
	transition: opacity 100ms ease-out, filter 100ms ease-out;
}

.mbv-operator-potential-image.is-blue {
	opacity: 0;
}

.mbv-operator-potential-toggle:hover .mbv-operator-potential-image:not(.is-blue),
.mbv-operator-potential-toggle:focus-visible .mbv-operator-potential-image:not(.is-blue),
.mbv-operator-potential-toggle.is-active .mbv-operator-potential-image:not(.is-blue) {
	opacity: 0;
}

.mbv-operator-potential-toggle:hover .mbv-operator-potential-image.is-blue,
.mbv-operator-potential-toggle:focus-visible .mbv-operator-potential-image.is-blue,
.mbv-operator-potential-toggle.is-active .mbv-operator-potential-image.is-blue {
	opacity: 1;
}

.mbv-operator-artwork-switch.clickable-icon:hover,
.mbv-operator-artwork-switch.clickable-icon:focus-visible,
.mbv-operator-potential-toggle.clickable-icon:hover,
.mbv-operator-potential-toggle.clickable-icon:focus-visible,
.mbv-operator-card .mbv-operator-potential-toggle.clickable-icon.is-active {
	filter:
		drop-shadow(0 0 3px rgb(255 255 255 / 32%))
		drop-shadow(0 0 6px rgb(0 184 237 / 58%));
	opacity: 1;
}

.mbv-operator-potential-toggle.is-saving {
	opacity: 0.55;
}

.mbv-operator-card.is-position-editing .mbv-operator-artwork {
	pointer-events: auto;
	touch-action: none;
	cursor: grab;
}

.mbv-operator-card.is-position-dragging .mbv-operator-artwork {
	cursor: grabbing;
}

.mbv-operator-card.is-position-editing .mbv-operator-shell {
	pointer-events: auto;
	transform: none;
}

.mbv-operator-card.is-position-editing {
	--mbv-operator-control-lift: 0px;
}

.mbv-operator-card.is-position-editing .mbv-operator-profession {
	filter: none;
	transform: translate3d(0, 0, 24px) scale(1);
}

.mbv-operator-card.is-position-editing .mbv-operator-faction {
	filter: none;
	transform: translate3d(0, 0, 22px) scale(1);
}

.mbv-operator-card.is-position-editing .mbv-operator-rarity {
	filter: none;
	transform: translate3d(0, 0, 28px) scale(1);
}
