/* Editing Suite 补充彩色语言图标: 结束 */

@media print {
	.editing-suite-sidenote-margin {
		display: none !important;
	}

	.print .editing-suite-print-footnotes {
		display: block;
		clear: both;
		margin-top: 2em;
		color: var(--text-normal);
		font-family: var(--font-text);
		font-size: 0.85em;
		line-height: 1.45;
	}

	.print .editing-suite-print-footnotes > hr {
		margin: 1.5em 0 1em;
		border: 0;
		border-top: 1px solid var(--background-modifier-border);
	}

	.print .editing-suite-print-footnotes > ol {
		margin: 0;
		padding: 0;
		list-style: none;
	}

	.print .editing-suite-print-footnotes > ol > li {
		display: grid;
		grid-template-columns: 1.4rem minmax(0, 1fr);
		align-items: start;
		column-gap: 0.6em;
		margin: 0.65em 0;
		break-inside: avoid;
		page-break-inside: avoid;
	}

	.print .editing-suite-print-footnote-number {
		margin-top: 0.15em;
	}

	.print .editing-suite-print-footnote-content {
		min-width: 0;
	}

	.print .editing-suite-print-footnote-content > :first-child {
		margin-top: 0;
	}

	.print .editing-suite-print-footnote-content > :last-child {
		margin-bottom: 0;
	}
}
